export type InstallChoice = {
	root: string,
	/**  Flavor folder name, e.g. "_classic_beta_". */
	flavor: string,
	/**
	 *  Where the flavor's linked folders (WTF, Interface/AddOns) pointed when
	 *  the user confirmed this install. Recorded once by `install::set`; game
	 *  paths are checked against these, so a link re-pointed later is refused
	 *  instead of silently followed.
	 */
	links?: LinkedFolder[],
};

/**
 *  The only keys the app stores. A closed enum, so the frontend can't write
 *  arbitrary keychain entries.
 */
export type IntegrationId = "curseforge" | "wago" | "wago_io" | "github" | "battlenet_client_id" | "battlenet_client_secret";

export type IntegrationSetting = {
	enabled?: boolean,
};

/**  A closed set: each optional integration is a named field, never a free-form key. */
export type Integrations = {
	curseforge?: IntegrationSetting,
	wago?: IntegrationSetting,
	wago_io?: IntegrationSetting,
	github?: IntegrationSetting,
	battlenet?: IntegrationSetting,
};

export type IntegrationsPatch = {
	curseforge?: IntegrationSetting | null,
	wago?: IntegrationSetting | null,
	wago_io?: IntegrationSetting | null,
	github?: IntegrationSetting | null,
	battlenet?: IntegrationSetting | null,
};

/**  One item in a slot, ready to show. */
export type ItemRow = {
	container: number,
	slot: number,
	item_id: number,
	name: string,
	/**  0 poor … 5 legendary, when known. */
	quality: number | null,
	ilvl: number | null,
	count: number,
};

/**  An interrupted restore: enough to roll it back or run it again. */
export type Journal = {
	/**  The snapshot the user chose to restore. */
	source_snapshot: string,
	/**
	 *  Taken before the user's restore changed anything. Rolling back always
	 *  restores this one, even after an interrupted recovery.
	 */
	original_pre_restore: string,
	/**
	 *  Taken before the latest attempt (the restore, or a recovery of it).
	 *  Equal to `original_pre_restore` on the first attempt.
	 */
	pre_restore_snapshot: string,
	selection: RestoreSelection,
	mode: RestoreMode,
	flavor: string,
	started_at: string,
	/**  The restore's one-line summary, for the recovery prompt. */
	summary: string,
};

/**  What to do about a restore that was interrupted. */
export type JournalAction = 
/**  Put back what was there before the restore started (recommended). */
"roll_back" | 
/**  Run the restore again to completion. */
"finish" | 
/**
 *  Forget it without changing files (e.g. the journal is unreadable).
 *  Its pre-restore snapshot stays in the Safety list.
 */
"discard";

export type JournalEntry = {
	adventure_id: number,
	character_id: number,
	name: string,
	login: string,
	logout: string | null,
	played_secs: number | null,
	gold_delta: number | null,
	/**  The level reached, if the character levelled. */
	level: number | null,
	of_note: OfNote | null,
};

/**
 *  Money is copper, as `f64` so TypeScript can hold it safely (specta sends
 *  no `i64`). Times are RFC 3339, UTC.
 */
export type Ledger = {
	/**
	 *  The earliest gold point ("from every logout since 2 Sep"); `None`
	 *  until the addon has written anything.
	 */
	since: string | null,
	tiles: Tiles,
	chart: Chart,
	journal: JournalEntry[],
};

export type LedgerExport = 
/**  The chart as a table: a row per day, a column per character. */
"gold" | 
/**  The journal: a row per adventure. */
"journal";

export type LedgerRange = "week" | "month" | "quarter" | "all";

export type LinkedFolder = {
	/**  `/`-separated path relative to the game root, e.g. "WTF". */
	folder: string,
	/**
	 *  Canonical target recorded at validation, e.g. `D:\Dropbox\WTF`.
	 *  The UI shows it as "WTF is linked to …".
	 */
	target: string,
};

export type LookedIn = {
	source: CandidateSource,
	path: string,
};

export type MailRow = {
	/**  Other players' text from your own mailbox: shown here, never exported. */
	sender: string | null,
	subject: string | null,
	money: number | null,
	cod: number | null,
	days_left: number | null,
	items: ItemRow[],
};

export type MailView = {
	as_of: string | null,
	messages: MailRow[],
};

/**
 *  The journal's "Of note" (spec §5): a level-up, else the zone with the most
 *  time and the quest count, else the biggest gain.
 */
export type OfNote = {
	text: string,
	/**  For an item: its quality, for the letter tile's colour. */
	quality: number | null,
};

/**  Files to write in one folder, for "…\Thrandor\SavedVariables\ (41 files)". */
export type PlanFolder = {
	/**  Relative to the flavor folder, `/`-separated. */
	folder: string,
	files: string[],
	bytes: number | null,
};

export type PlaySession = {
	/**
	 *  A row id; `u32` because specta won't send an `i64` to TypeScript, and
	 *  four billion sessions is plenty.
	 */
	id: number,
	flavor: string,
	/**  RFC 3339, UTC. */
	started_at: string,
	/**  `None` while WoW is still running. */
	ended_at: string | null,
	/**
	 *  Characters whose settings changed during the session, in WTF folder
	 *  order. Empty while running, or if nothing changed (e.g. WoW was
	 *  closed at character select).
	 */
	characters: CharacterRef[],
	/**
	 *  WoW wrote a crash report (`<flavor>/Errors`) during the run. A process
	 *  killed without one can't be told apart from a clean exit.
	 */
	crashed: boolean,
};

export type ProfessionRow = {
	name: string,
	skill: number | null,
	max: number | null,
};

/**  What a prune did. */
export type PruneReport = {
	pruned: string[],
	blobs_removed: number,
	freed_bytes: number | null,
	/**  Store size on disk afterwards. */
	used_bytes: number | null,
	budget_bytes: number | null,
	/**
	 *  Still over budget after pruning everything allowed (only manual,
	 *  pinned or the newest few are left): the UI shows a warning.
	 */
	over_budget: boolean,
};

/**  What the UI shows about interrupted restores. */
export type RecoveryStatus = 
/**  No interrupted restore. */
{ kind: "none" } | 
/**  Roll back, finish or leave as is. */
{ kind: "pending"; journal: Journal } | 
/**
 *  A journal exists but can't be read, so roll back and finish aren't
 *  possible. `latest_safety` is the newest pre-restore snapshot, for
 *  "Open the safety copy"; clearing the notice discards the journal.
 */
{ kind: "unreadable"; error: string; latest_safety: string | null };

/**
 *  A path relative to a base folder (usually the flavor dir) that can't name
 *  anything outside it (spec §4). Stored as components and written with `/`,
 *  which is also the format backup manifests use (`WTF/Account/X/...`).
 * 
 *  Rejected: empty paths, absolute paths, drive (`C:`) and UNC prefixes, `.`
 *  and `..`, `:` anywhere (drives, NTFS alternate data streams), NUL,
 *  components ending in a dot or space (Windows strips those, so `a.` would
 *  alias `a`), and DOS device names like `CON` or `com1.txt`.
 */
export type RelPath = string;

/**  Emitted when a restore (or a recovery) has finished. */
export type RestoreCompleted = RestoreReport;

/**
 *  Overlay writes the snapshot's files and leaves others alone (the default
 *  for every scope). Mirror also removes files under the scope that the
 *  snapshot doesn't have.
 */
export type RestoreMode = "overlay" | "mirror";

export type RestorePlan = {
	snapshot_id: string,
	mode: RestoreMode,
	write: PlanFolder[],
	write_count: number,
	/**  Shown prominently, with its own count, in the confirm dialog. */
	delete: string[],
	/**  Files that already match the snapshot. */
	unchanged: number,
	bytes: number | null,
	/**
	 *  Targets marked read-only. The restore refuses until the flag is
	 *  cleared; players do this on purpose (e.g. to pin Config.wtf).
	 */
	read_only: string[],
	/**
	 *  Files (or folders) in the selection that the snapshot couldn't read
	 *  at the time: not in this backup, so left as they are, never deleted.
	 */
	not_backed_up: string[],
	/**  "keybindings, macros and 41 addon settings". */
	summary: string,
};

/**  Emitted while a restore runs. */
export type RestoreProgress = {
	done: number,
	total: number,
};

export type RestoreReport = {
	snapshot_id: string,
	/**
	 *  The safety snapshot taken before anything changed; `None` if there
	 *  was nothing to do.
	 */
	pre_restore_snapshot: string | null,
	written: number,
	deleted: number,
	summary: string,
};

/**  What to restore. A file is restored if any item matches it. */
export type RestoreSelection = {
	items: ScopeItem[],
};

export type Scope = 
/**  The whole tree that backups cover. */
"full" | 
/**  Only specific paths (safety snapshots before a write). */
"partial";

export type ScopeItem = 
/**  Every file in the snapshot. */
{ kind: "Everything" } | 
/**  Account-wide files (not its characters). `None` = every category. */
{ kind: "Account"; account: string; categories: Category[] | null } | 
/**  One character's folder. `None` = every category. */
{ kind: "Character"; account: string; realm: string; character: string; categories: Category[] | null } | 
/**  One addon's SavedVariables (`<addon>.lua` and `.lua.bak`). */
{ kind: "AddonData"; addon: string; target: AddonTarget } | 
/**  Exact files or folders, relative to the flavor folder. */
{ kind: "Paths"; paths: RelPath[] };

/**
 *  One row of the Integrations panel. Each id is checked on its own, so one
 *  unreadable credential shows as that row's error instead of failing all.
 */
export type SecretStatus = {
	id: IntegrationId,
	is_set: boolean,
	/**  Why the store couldn't be read for this id. Never contains the value. */
	error: string | null,
};

export type Series = {
	/**  `None` for the "others" line. */
	character_id: number | null,
	name: string,
	/**  How many characters the "others" line adds up; 1 for a character. */
	count: number,
	/**  Per day; `None` before the character's first point. */
	values: (number | null)[],
};

/**  Emitted when a session starts, ends, or learns its characters. */
export type SessionsChanged = null;

/**
 *  settings.json (spec §6). Every field has a default, so a missing key never
 *  fails a load. Keys this build doesn't know are kept on disk by
 *  `SettingsStore`, at any depth, so a downgrade never wipes them.
 */
export type Settings = {
	/**  Backend-owned: set by load/migrate, ignored on update. */
	schema_version?: number,
	/**  Backend-owned: changed only through install commands, which validate it. */
	install?: InstallChoice | null,
	backup?: BackupSettings,
	/**  Extra game process names to treat as WoW, e.g. if Forever's exe has an unusual name. */
	process_names_extra?: string[],
	integrations?: Integrations,
	/**
	 *  Free-form UI preferences (remembered tabs, filters). The backend never reads it.
	 *  Strings only; the frontend JSON-encodes anything structured.
	 */
	ui?: { [key in string]: string },
};

/**
 *  A partial update from the UI (spec §8 `settings_update(patch)`): only the
 *  fields present change, so a stale copy of the settings can't overwrite
 *  newer values. There are no `install` or `schema_version` fields, and
 *  unknown fields are rejected, so a patch can't touch backend-owned state.
 */
export type SettingsPatch = SettingsPatch_Serialize | SettingsPatch_Deserialize;

/**
 *  A partial update from the UI (spec §8 `settings_update(patch)`): only the
 *  fields present change, so a stale copy of the settings can't overwrite
 *  newer values. There are no `install` or `schema_version` fields, and
 *  unknown fields are rejected, so a patch can't touch backend-owned state.
 */
export type SettingsPatch_Deserialize = {
	backup?: BackupPatch_Deserialize | null,
	process_names_extra?: string[] | null,
	integrations?: IntegrationsPatch | null,
	/**  Set keys to a string to store them, or to null to remove them. */
	ui?: { [key in string]: string | null } | null,
};

/**
 *  A partial update from the UI (spec §8 `settings_update(patch)`): only the
 *  fields present change, so a stale copy of the settings can't overwrite
 *  newer values. There are no `install` or `schema_version` fields, and
 *  unknown fields are rejected, so a patch can't touch backend-owned state.
 */
export type SettingsPatch_Serialize = {
	backup: BackupPatch_Serialize | null,
	process_names_extra: string[] | null,
	integrations: IntegrationsPatch | null,
	/**  Set keys to a string to store them, or to null to remove them. */
	ui: { [key in string]: string | null } | null,
};

/**  A file a full snapshot left out, and why. */
export type SkippedFile = {
	/**
	 *  Relative to the flavor folder when it could be expressed that way;
	 *  otherwise the path as the OS reported it.
	 */
	path: string,
	reason: string,
};

export type SnapshotDetail = {
	summary: SnapshotSummary,
	accounts: AccountNode[],
	addons: AddonNode[],
	/**  Files outside `WTF/Account` (e.g. `WTF/Config.wtf`, AddOns folders). */
	other: Totals,
	/**  Files the snapshot couldn't capture and left out (R1). */
	skipped: SkippedFile[],
};

export type SnapshotKind = "Manual" | "Auto" | "Safety";

/**  One row of the Backups list. */
export type SnapshotSummary = {
	id: string,
	created_at: string,
	trigger: Trigger,
	kind: SnapshotKind,
	label: string | null,
	pinned: boolean,
	scope: Scope,
	flavor: string,
	game_running: boolean,
	file_count: number,
	char_count: number,
	addon_count: number,
	/**
	 *  Bytes are f64 because TypeScript numbers can't hold a u64 safely;
	 *  exact up to 9 PB.
	 */
	total_bytes: number | null,
	new_bytes: number | null,
};

export type StartupFailure = {
	problem: StartupProblem,
	/**  The error, for "Error details" and "Copy error details". */
	message: string,
	paths: AppPaths,
	/**  The file at fault, shown in red; `None` if it isn't one file. */
	at_fault: string | null,
};

/**  Which of the app's files is the problem, so the UI can mark it. */
export type StartupProblem = 
/**  `buddy.db`, e.g. written by a newer version of the app. */
"database" | 
/**  `settings.json`. */
"settings" | 
/**  Anything else, e.g. a data folder that can't be created. */
"other";

/**  The storage meter on the Backups screen. */
export type StorageInfo = {
	used_bytes: number | null,
	budget_bytes: number | null,
	over_budget: boolean,
	/**  Generated from the policy, shown as is (spec §5). */
	retention_summary: string,
	/**
	 *  Cleanup is refused because a snapshot's record is damaged (which
	 *  one, and why), so the budget isn't being enforced. Shown as a warning.
	 */
	cleanup_blocked: string | null,
};

export type Tiles = {
	/**  Every character's latest money, added up. */
	account_gold: number | null,
	characters: number,
	/**
	 *  What the account gained (or lost) over 30 and 7 days. A character
	 *  first seen inside the window counts from its first point, so a new
	 *  character's starting gold isn't "earned".
	 */
	last_30_days: number | null,
	this_week: number | null,
	best_earner: Earner | null,
};

export type Totals = {
	files: number,
	/**  f64 so TypeScript can hold it safely. */
	bytes: number | null,
};

export type Trigger = "manual" | "app_start" | "game_exit" | "scheduled" | "pre_write" | "pre_restore";

export type VerifyReport = {
	snapshot_id: string,
	files: number,
	/**  Files whose stored copy is missing, unreadable or fails its checksum. */
	corrupt: string[],
	/**  Those of `corrupt` whose stored copy is gone. */
	missing: string[],
	/**  Those of `corrupt` whose copy couldn't be read right now (retry). */
	unreadable: string[],
};

/**  A location the addon only sees when it's opened (bank, mailbox). */
export type Visited = {
	/**  When it was last seen (RFC 3339), `None` if never. */
	as_of: string | null,
	bags: BagView[],
};

/**  A character found in the WTF folder. */
export type WtfCharacter = {
	/**
	 *  When any file in its folder last changed (RFC 3339, UTC): close to
	 *  when it was last logged out.
	 */
	last_played: string | null,
	/**
	 *  An older settings folder: the layout from before surnames, next to
	 *  the new one (`install::wtf::older_groups`). Listed apart, not counted,
	 *  and never a session's character.
	 */
	older: boolean,
} & CharacterRef;

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

